mapper.sql:
select u.id as userId,
       u.username as username,
       u.name as name,
       u.dept_id as deptId,
       d.name as deptName
from sys_user u
    left join sys_dept d on d.id = u.dept_id

    and u.is_deleted = 0
    and (
        (u.status = 1 and exists (
            select 1 from attendance_group_member m where m.user_id = u.id
        ))
        or exists (
            select 1 from attendance_punch p
            where p.user_id = u.id
              and p.is_deleted = 0
              and p.punch_date >= #{beginDate}
              and p.punch_date <= #{endDate}
        )
    )



                and (u.dept_id in

                    #{deptId}


                    or u.id = #{scope.selfUserId}

                )


                and u.id = #{scope.selfUserId}


                and 1 = 0
